INSERT INTO archive_user_cr (id, session_id, user_id, content, updated_at) VALUES (1, 10, 1, $val$Panda: J'ai pris une fessée, et j'ai aimé :s
INSERT INTO archive_user_cr (id, session_id, user_id, content, updated_at) VALUES (2, 10, 3, $val$2ème Lacerda pour moi, et celui-ci m'a semblé plus accessible que Kanban EV. Les actions disponibles sont finalement assez limitées en nombre, mais c'est l'ordonnancement qui fait toute la profondeur du jeu — ainsi que l'anticipation des mouvements adverses. La mécanique d'action entre les tours réduit considérablement le downtime et génère de belles opportunités de combos, tout en introduisant une dimension de déduction et de lecture des autres joueurs. On est moins dans le "deny" que dans le balet. Le tout est remarquablement bien équilibré.
INSERT INTO archive_user_cr (id, session_id, user_id, content, updated_at) VALUES (3, 10, 2, $val$Ah bah si, là, après refresh, la page semble avoir changé de fonctionnement et permettre des comptes-rendus par participant plutôt qu'un champs global pour tous les participants.
INSERT INTO archive_user_cr (id, session_id, user_id, content, updated_at) VALUES (25, 8, 3, $val$Grosse journée jeux : Cyclade nous a laissés sur notre faim (frustrant et déséquilibré), mais Sidéral Confluence et Hot Streaks ont largement rattrapé le coup — table en ébullition, franches rigolades, négociations endiablées.
INSERT INTO archive_user_cr (id, session_id, user_id, content, updated_at) VALUES (32, 8, 1, $val$2 gros jeux, un filler con, une tête de cochon (moi 🐖), un cadeau d'anniversaire en retard 🥳, de la bonne bouffe et de la bonne compagnie.
INSERT INTO archive_user_cr (id, session_id, user_id, content, updated_at) VALUES (51, 8, 2, $val$"Est-ce que quelqu'un a un gros cube noir à échanger?"
INSERT INTO archive_user_cr (id, session_id, user_id, content, updated_at) VALUES (86, 9, 1, $val$$val$, $val$2026-04-28 10:00:29$val$);
INSERT INTO archive_game_cr (id, game_id, user_id, content, updated_at) VALUES (1, 67, 3, $val$Fall Guys version PMU... moi j'achète.
INSERT INTO archive_game_cr (id, game_id, user_id, content, updated_at) VALUES (3, 67, 2, $val$Fun, imprévisible, délicieusement visuel et débile. Convient parfaitement à notre équipe de dégénérés.
INSERT INTO archive_game_cr (id, game_id, user_id, content, updated_at) VALUES (5, 66, 3, $val$Très bonne surprise. Table en ébullition du début à la fin.
INSERT INTO archive_game_cr (id, game_id, user_id, content, updated_at) VALUES (10, 66, 1, $val$Des cubes partoooouuuuuutttt.
INSERT INTO archive_game_cr (id, game_id, user_id, content, updated_at) VALUES (11, 67, 1, $val$Quand je vous dis que j'ai des trucs cons, j'ai des trucs cons !!!
INSERT INTO archive_game_cr (id, game_id, user_id, content, updated_at) VALUES (13, 66, 2, $val$Belle découverte du jour, une bonne interaction, des différences notables entre les factions sans que l'une ressorte plus forte que l'autre. La négociation est au cœur du jeu et il y aura toujours une chouineuse pour mendier un dernier cube de telle ou telle couleur. On en remettra volontiers une :)
INSERT INTO archive_game_cr (id, game_id, user_id, content, updated_at) VALUES (15, 72, 1, $val$C'est peut-être un bon jeu, mais c'est pas fait pour moi, désolé Shamu.
INSERT INTO archive_game_cr (id, game_id, user_id, content, updated_at) VALUES (21, 72, 3, $val$Mécanique originale et thème vraiment bien trouvé, mais la partie s'est avérée frustrante en pratique.
INSERT INTO archive_game_cr (id, game_id, user_id, content, updated_at) VALUES (24, 72, 2, $val$2ème partie de Cyclades pour moi, avec les mêmes constats que la première.
